function previewItems(snapshot,outputs=[]){
  if(!snapshot)return [];
  const item=(id,title,side)=>({id,title,regions:(snapshot.mappings||[]).filter(m=>m[side].image_id===id).map(m=>({mask_id:m[side].mask_id,anchor:m[side].anchor,number:m.display_index,color:m.color}))});
  const references=snapshot.references||[];
  return [...outputs.map((id,i)=>({id,title:`生成结果${outputs.length>1?' '+(i+1):''}`,regions:[]})),
    ...(snapshot.main_image?[item(snapshot.main_image,'原主图','target')]:[]),
    ...references.map((id,i)=>item(id,`参考图 ${i+1}`,'source'))];
}
function previewAsset(id,marked=false){const items=previewItems(previewSnapshot?.state||state,previewSnapshot?.outputs||[]),index=items.findIndex(item=>item.id===id),item=items[index]||{id,title:'图片',regions:[]};if(previewSnapshot){openPreview(items,Math.max(0,index),marked);return;}const side=id===state.main_image?'main':'reference';openPreview([item],0,marked,{minimal:true,onDraw:async points=>{if(panels[side]?.id!==id)throw new Error('图片已切换，请重新打开');startDrawing(side);polygon=points;await finishDrawing();},onRegionDrop:side==='reference'?(region,x,y)=>dropPreviewRegion(id,region,x,y):null,onClose:()=>{if(drawMode)cancelSelection();}});}
async function dropPreviewRegion(imageId,region,x,y){const original=state.mappings.find(m=>m.display_index===region.number&&m.source.image_id===imageId);if(!original)return false;const point=pointAt('main',{clientX:x,clientY:y});if(!point){toast('未落到主图，已恢复大图前状态');return false;}pending={source:clone(original.source),anchor:point};panels.main.selection=null;setStatus('main','等待目标确认 · 识别或手动圈选');selectionBar();await requestSelection('main',point,performance.now());return true;}
document.addEventListener('click',event=>{
  const img=event.target.closest('img');if(!img||img.closest('.image-viewer,.composer-shell'))return;
  const id=new URL(img.src,location.href).pathname.match(/^\/api\/assets\/([a-f0-9]{32})$/)?.[1];if(!id)return;
  if(img.closest('.history-card'))return;
  event.preventDefault();event.stopPropagation();
  const selector=img.closest('[data-ref],[data-output]');if(selector)selector.click();
  previewAsset(id);
},true);

async function api(path,options={}){
  const init={...options,headers:{...options.headers}};
  if(init.body&&!(init.body instanceof FormData)){init.headers['Content-Type']='application/json';init.body=JSON.stringify(init.body);}
  const r=await fetch('/api'+path,init);const data=await r.json();if(!r.ok)throw Object.assign(new Error(typeof data.detail==='string'?data.detail:data.detail?.message||'请求失败，请检查编辑数据'),{status:r.status});return data;
}
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),5000);}
function safe(fn){return (...args)=>{try{return Promise.resolve(fn(...args)).catch(e=>toast(e.message));}catch(e){toast(e.message);}};}
async function getMeta(id){if(!metaCache.has(id))metaCache.set(id,await api(`/assets/${id}/meta`));return metaCache.get(id);}
async function getImage(id){if(!imageCache.has(id)){const im=new Image();im.src=url(id);await im.decode();imageCache.set(id,im);}return imageCache.get(id);}
function shell(active){$('#app').innerHTML=`<header><a class="brand" href="/" data-nav><span class="brand-icon">↗</span>拾影<span class="brand-en">STUDIO</span></a><nav><a href="/" data-nav class="${active==='editor'?'active':''}">编辑工作区</a><a href="/history" data-nav class="${active==='history'?'active':''}">生成历史</a></nav><div class="header-right"><span class="model-pill"><i></i>Image2.5</span><button class="text-btn" id="logout">退出</button></div></header><main id="page"></main><footer>拾取灵感，定向编辑。<span>素材与编辑记录保存在你的私有空间</span></footer>`;$('#logout').onclick=safe(async()=>{await api('/logout',{method:'POST'});location.reload();});}
function bindNav(){document.querySelectorAll('[data-nav]').forEach(a=>a.onclick=safe(async e=>{e.preventDefault();await navigate(a.getAttribute('href'));}));}
