function login(){ $('#app').innerHTML=`<div class="login"><span class="brand-icon">↗</span><h1>欢迎回到拾影</h1><p>你的 Image2.5 私有编辑工作室</p><form id="login"><label>空间密码<input type="password" name="password" autocomplete="current-password" required placeholder="输入服务端配置的空间密码"></label><button class="primary" type="submit">进入工作室 →</button><p id="login-error" role="alert"></p></form><small>原图、关系和历史均由本站持久保存</small></div>`;$('#login').onsubmit=async e=>{e.preventDefault();try{await api('/login',{method:'POST',body:{password:new FormData(e.target).get('password')}});await boot();}catch(err){$('#login-error').textContent=err.message;}};}
async function route(){clearTimeout(pageTimer);resetSelection();const path=location.pathname;if(path.startsWith('/history/'))await detail(path.split('/')[2]);else if(path==='/history')await historyPage();else await editor();bindNav();}
window.addEventListener('popstate',safe(async()=>{if(state&&dirty!==saved)await save();await route();}));
